#include <iostream>
#include <map>
using namespace std;

using LL = long long;

const int MOD = 1000000007;
const int MAX_N = 51;

LL T[MAX_N + 1], B[MAX_N + 1];
map<int, LL> vis;

void get_bell(int n, int mod) {
    B[0] = 1;
    T[0] = 1;

    for (int i = 1; i <= n; ++i) {
        T[i] = T[i - 1];
        for (int j = i - 1; j > 0; --j)
            T[j] = (T[j - 1] + T[j]) % mod;
        T[0] = T[i];
        B[i] = T[0];
    }
}

LL bell_mod_impl(int n, int mod) {
    if (n <= MAX_N)
        return B[n];

    auto it = vis.find(n);
    if (it != vis.end())
        return it->second;

    LL p = mod;
    LL k = 1;
    while (p <= n / mod) {
        p *= mod;
        ++k;
    }

    return vis[n] =
        (k * bell_mod_impl(static_cast<int>(n - p), mod) +
         bell_mod_impl(static_cast<int>(n - p + 1), mod)) % mod;
}

LL bell_mod(int n, int mod) {
    vis.clear();
    return bell_mod_impl(n, mod);
}

int main() {
    get_bell(MAX_N, MOD);

    int n;
    cin >> n;

    LL a = bell_mod(n + 1, MOD);
    LL b = bell_mod(n, MOD);
    cout << (a - b + MOD) % MOD << '\n';

    return 0;
}

